char32_t game_codepoint(uint8_t b){
 // Kamenicky mapping facts cross-checked against the embedded glyphs; see text-font.json.
 static constexpr std::array<char32_t,128> high{0x10c,0xfc,0xe9,0x10f,0xe4,0x10e,0x164,0x10d,0x11b,0x11a,0x139,0xcd,0x13e,0x13a,0xc4,0xc1,0xc9,0x17e,0x17d,0xf4,0xf6,0xd3,0x16f,0xda,0xfd,0xd6,0xdc,0x160,0x13d,0xdd,0x158,0x165,0xe1,0xed,0xf3,0xfa,0x148,0x147,0x16e,0xd4,0x161,0x159,0x155,0x154,0xbc,0xa7,0xab,0xbb,0x2591,0x2592,0x2593,0x2502,0x2524,0x2561,0x2562,0x2556,0x2555,0x2563,0x2551,0x2557,0x255d,0x255c,0x255b,0x2510,0x2514,0x2534,0x252c,0x251c,0x2500,0x253c,0x255e,0x255f,0x255a,0x2554,0x2569,0x2566,0x2560,0x2550,0x256c,0x2567,0x2568,0x2564,0x2565,0x2559,0x2558,0x2552,0x2553,0x256b,0x256a,0x2518,0x250c,0x2588,0x2584,0x258c,0x2590,0x2580,0x3b1,0xdf,0x393,0x3c0,0x3a3,0x3c3,0xb5,0x3c4,0x3a6,0x398,0x3a9,0x3b4,0x221e,0x3c6,0x3b5,0x2229,0x2261,0xb1,0x2265,0x2264,0x2320,0x2321,0xf7,0x2248,0xb0,0x2219,0xb7,0x221a,0x207f,0xb2,0x25a0,0xa0};
 return b<128?char32_t(b):high[b-128];
}
std::vector<std::byte> decrypt_game_text(ByteView bytes){
 // Verified DOS text transform at 0x2154e; the key is shipped artifact data.
 constexpr std::string_view key="Vyvojovy tym AGDS varuje: Hackerovani skodi obchodu!";
 std::vector<std::byte> out;out.reserve(bytes.size());for(size_t i=0;i<bytes.size();++i)out.push_back(bytes[i]^std::byte(key[i%key.size()])^std::byte{255});return out;
}
namespace {void utf8(std::string& out,char32_t c){if(c<128)out+=char(c);else if(c<2048){out+=char(0xc0|(c>>6));out+=char(0x80|(c&63));}else{out+=char(0xe0|(c>>12));out+=char(0x80|((c>>6)&63));out+=char(0x80|(c&63));}}}
Result<GameText> parse_game_text(ByteView bytes,GameEncoding){
 GameText out;for(size_t i=0;i<bytes.size();++i){auto c=std::to_integer<uint8_t>(bytes[i]);if(c==0||c==13||c==10||c==';'){out.controls.push_back({i,out.utf8.size(),c});if(!c)break;if(c==10||c==';')out.utf8+='\n';continue;}if(c<32)return DataError{"","text",i,"unmapped text control byte"};utf8(out.utf8,game_codepoint(c));}return out;
}
Result<std::string> decode_game_text(ByteView bytes,GameEncoding e){auto r=parse_game_text(bytes,e);if(!r.has_value())return r.error();return std::move(r.value().utf8);}
